import java.io.*;
import java.util.*;

public class Main {
    private static final int BUF = 1 << 16;
    private static final byte[] buf = new byte[BUF];
    private static int ptr = 0, len = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(buf, 0, BUF);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    private static int readInt() throws IOException {
        int c = read();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == '\f') c = read();
        boolean neg = false;
        if (c == '-') { neg = true; c = read(); }
        int x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = read();
        }
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int n = readInt();
        int t = readInt();
        int[] typ = new int[n];
        int[] prc = new int[n];
        for (int i = 0; i < n; i++) typ[i] = readInt();
        for (int i = 0; i < n; i++) prc[i] = readInt();
        int c = readInt();

        // Min-heap de preços por tipo (objetos disponíveis)
        @SuppressWarnings("unchecked")
        PriorityQueue<Integer>[] heaps = new PriorityQueue[t + 1];
        // Conjunto global ordenado por (preço, tipo) - um par por objeto disponível
        TreeSet<Long> global = new TreeSet<>();

        for (int i = 0; i < n; i++) {
            int tt = typ[i], pp = prc[i];
            PriorityQueue<Integer> h = heaps[tt];
            if (h == null) { h = new PriorityQueue<>(); heaps[tt] = h; }
            h.add(pp);
            global.add((((long) pp) << 17) | (long) tt); // t < 2^17, p < 2^20
        }

        long total = 0;
        for (int j = 0; j < c; j++) {
            int u = readInt();
            if (u != 0) {
                // Cliente decidido: menor preço do tipo u
                PriorityQueue<Integer> h = heaps[u];
                if (h != null && !h.isEmpty()) {
                    int p = h.poll();
                    global.remove(((long) p << 17) | (long) u);
                    total += p;
                }
            } else {
                // Cliente indeciso: menor (preço, tipo) global
                if (!global.isEmpty()) {
                    long key = global.pollFirst();
                    int p = (int) (key >>> 17);
                    int tt = (int) (key & 131071L);
                    heaps[tt].poll();
                    total += p;
                }
            }
        }
        System.out.println(total);
    }
}
